template:
fn duplicate_first(nums: &mut Vec<i32>) {
    if nums.is_empty() { return; }
    let val = ⟦val_expr⟧;
    nums.push(⟦push_expr⟧);
    println!("{val}");
}

fn main() {
    let mut v = vec![10, 20];
    duplicate_first(&mut v);
    println!("{v:?}");
}

tests:
#[test]
fn duplicates() {
    let mut v = vec![3, 7];
    duplicate_first(&mut v);
    assert_eq!(v, vec![3, 7, 6]);
}
